INSERT INTO `library_resources` (`id`, `slug`, `resource_type`, `title`, `title_en`, `summary`, `body`, `creator`, `publisher`, `publication_year`, `publication_date`, `isbn`, `doi`, `source_url`, `file_url`, `image_url`, `video_url`, `embed_url`, `duration_seconds`, `language`, `meta_title`, `meta_description`, `status`, `created_at`, `updated_at`, `published_at`) VALUES
('res-e081bac707848a7377a4', 'نظریه-های-ارتباطات-54b389', 'book', 'نظریه‌های ارتباطات', 'Communication Theories', 'این کتاب «نظریه‌های ارتباطات» (Communication Theories) نوشته ورنر جوزف سورین و جیمز دبلیو تانکارد، یکی از منابع کلاسیک و پرمرجع در حوزه ارتباطات جمعی است که به بررسی مبانی، روش‌ها و کاربردهای نظریه‌های ارتباطی می‌پردازد.', '📖 درباره اصل کتاب و نویسنده\nکتاب اصلی با عنوان کامل Communication Theories: Origins, Methods, and Uses in the Mass Media منتشر شده و تاکنون ویرایش‌های متعددی از آن (از جمله ویرایش پنجم در سال ۲۰۰۱) به چاپ رسیده است . این اثر به عنوان یک کتاب درسی دانشگاهی، مروری جامع بر نظریه‌های تأثیرگذار در ارتباطات جمعی، سیر تحول آن‌ها و همچنین مباحث جدیدتر مانند رسانه‌های دیجیتال ارائه می‌دهد .\n\n📚 درباره ترجمه فارسی\nاین کتاب توسط علیرضا دهقان به فارسی برگردانده شده و توسط مؤسسه انتشارات دانشگاه تهران منتشر شده است. بر اساس اطلاعات کتابخانه ملی، این ترجمه شامل ۵۷۵ صفحه است و عنوان اصلی کتاب نیز در مشخصات آن ذکر شده است .\n\n🔗 ارتباط با نظریه‌های ارتباطی\nاین کتاب به طور مشخص با طیف وسیعی از نظریه‌های کلاسیک و مدرن ارتباطات جمعی مرتبط است. بر اساس فهرست فصل‌های ترجمه فارسی، می‌توان ارتباط آن را با نظریه‌های زیر مشاهده کرد :\n\n    نظریه‌های اقناع و تبلیغات: فصل نهم به طور مستقیم به نظریه‌های اقناع (Persuasion) اختصاص دارد و فصل ششم نیز به تحلیل تبلیغات (Propaganda) می‌پردازد.\n\n    هماهنگی شناختی: فصل هشتم به نظریه‌های هماهنگی شناختی (مانند نظریه تعادل هایدر و ناهماهنگی شناختی فستینگر) و ارتباط آن با رسانه‌های جمعی می‌پردازد.\n\n    برجسته‌سازی (Agenda Setting): فصل دوازدهم به طور کامل به نظریه برجسته‌سازی اختصاص یافته است.\n\n    شکاف آگاهی (Knowledge Gap): فصل سیزدهم به فرضیه شکاف آگاهی می‌پردازد.\n\n    استفاده و رضایت (Uses and Gratifications): فصل پانزدهم با عنوان «استفاده از رسانه‌های جمعی» به این رویکرد مرتبط است.\n\n    ارتباطات گروهی و میان‌فردی: فصل دهم به رابطه رسانه‌های جمعی و ارتباطات میان‌فردی (مانند جریان دو مرحله‌ای) می‌پردازد.\n\nاگرچه این کتاب صرفاً به یک نظریه خاص محدود نمی‌شود، اما به عنوان یک منبع جامع، چارچوبی برای درک و مقایسه بسیاری از نظریه‌های اصلی در حوزه ارتباطات جمعی فراهم می‌کند.', 'ورنر جوزف سورین و جیمز دبلیو تانکارد ترجمه علیرضا دهقان', 'مؤسسه انتشارات و چاپ دانشگاه تهران', 1381, NULL, '', '', '', '', 'https://www.iranketab.ir/Images/ProductImages/79ff2bab06634d3ba97bc039b2e0bee9.jpg', '', '', NULL, 'fa', '', '', 'published', '2026-11-03 18:59:17', '2026-11-03 18:59:17', '2026-11-03 18:59:17');
