INSERT INTO `theorists` (`id`, `name`, `name_en`, `slug`, `avatar_url`, `year`, `nationality`, `field`, `main_theory`, `bio`, `academic_career`, `quote`, `importance`, `cards_count`) VALUES
('th-1', 'ماکسول مک‌کامبز', 'Maxwell McCombs', 'maxwell-mccombs', '/images/theorists/maxwell-mccombs.jpg', '۱۹۷۲', 'آمریکایی', 'برجسته‌سازی و افکار عمومی', 'نظریه تعیین و برجسته‌سازی دستور کار (Agenda-Setting)', 'ماکسول مک‌کامبز (زاده ۱۹۳۸) از نامدارترین استادان علوم ارتباطات در دانشگاه تگزاس در آستین است. او به همراه دونالد شاو در سال ۱۹۷۲ مطالعه تاریخی «چپل هیل» را منتشر ساخت و اثبات نمود رسانه‌ها با برجسته کردن برخی موضوعات، اولویت‌های ذهنی و گفتمانی جامعه را شکل می‌دهند.', 'استاد ممتاز کرسی جسی اچ. جونز در دانشگاه تگزاس در آستین، ریاست اسبق انجمن پژوهش‌های روزنامه‌نگاری و ارتباطات جمعی (AEJMC)، مؤلف آثاری همچون «تنظیم دستور کار: رسانه‌های جمعی و افکار عمومی» و صدها مقاله علمی در ژورنال‌های معتبر.', 'رسانه‌ها لزوماً نمی‌گویند چگونه فکر کنیم، اما با موفقیتی شگفت‌انگیز به ما یاد می‌دهند به چه چیزی فکر کنیم.', 100, 6),
('th-10', 'هارولد لاسول', 'Harold Lasswell', 'harold-lasswell', '/images/theorists/harold-lasswell.jpg', '۱۹۴۸', 'آمریکایی', 'علوم سیاسی و تحلیل پروپاگاندا', 'مدل ارتباطی لاسول و کارکردهای سه‌گانه رسانه', 'هارولد دوایت لاسول (۱۹۰۲–۱۹۷۸) نظریه‌پرداز پیشگام ارتباطات و علوم سیاسی است. مدل خطی مشهور او («چه کسی می‌گوید، چه می‌گوید، در چه کانالی، به چه کسی، و با چه اثری») استاندارد پایه‌ای تحلیل محتوا و فرآیند پیام در تاریخ علم ارتباطات است.', 'استاد دانشگاه شیکاگو و دانشکده حقوق دانشگاه ییل، ریاست انجمن علوم سیاسی آمریکا، مؤلف آثار مرجع در تبلیغات جنگی، روان‌کاوی سیاسی و کارکرد رسانه‌ها.', 'ارتباطات ابزار حیاتی جامعه برای نظارت بر محیط، ایجاد همبستگی درونی و انتقال میراث مشترک به نسل‌های بعد است.', 92, 5),
('th-11', 'مانوئل کاستلز', 'Manuel Castells', 'manuel-castells', '/images/theorists/manuel-castells.jpg', '۱۹۹۶', 'اسپانیایی', 'جامعه‌شناسی اینترنت و عصر اطلاعات', 'جامعه شبکه‌ای و قدرت ارتباطات (Network Society)', 'مانوئل کاستلز اولیوان (زاده ۱۹۴۲) از پیشگامان نظریه‌پردازی درباره انقلاب فناوری اطلاعات است. سه‌گانه ماندگار او تحت عنوان «عصر اطلاعات» تغییر بنیادین در ساختار اقتصاد، فرهنگ و جنبش‌های اجتماعی از طریق شبکه‌های ارتباطی را تبیین نمود.', 'استاد ممتاز جامعه‌شناسی در دانشگاه کالیفرنیا در برکلی، استاد کرسی ارتباطات دانشگاه کالیفرنیای جنوبی، برنده جایزه هولبرگ و وزیر سابق علوم و دانشگاه‌های اسپانیا.', 'در عصر اطلاعات، نبرد اصلی بر سر تسخیر ذهن انسان‌ها در فضای شبکه‌های ارتباطی رخ می‌دهد.', 96, 4),
('th-12', 'رابرت انتمن', 'Robert Entman', 'robert-entman', '/images/theorists/robert-entman.svg', '۱۹۹۳', 'آمریکایی', 'ارتباطات سیاسی و تحلیل اخبار', 'مکانیسم چهارگانه چارچوب‌بندی (Framing Paradigm)', 'رابرت ام. انتمن استاد بازنشسته رسانه و امور بین‌الملل در دانشگاه جرج واشنگتن است. مقاله جاودانه او در سال ۱۹۹۳ تحت عنوان «چارچوب‌بندی: به سوی شفاف‌سازی یک پارادایم شکسته» دقیق‌ترین تعریف کاربردی از انتخاب و برجسته‌سازی در پیام‌های رسانه‌ای را بنیان نهاد.', 'استاد کرسی جی. بی. و موریس سی. شاپیرو در دانشگاه جرج واشنگتن، برنده جایزه دستاورد عمر علمی انجمن بین‌المللی ارتباطات (ICA)، مؤلف کتاب «آبشار رسانه‌ای و قدرت سیاسی».', 'چارچوب‌بندی یعنی برگزیدن بخش‌هایی از واقعیت و معنادار ساختن آن‌ها از طریق تعریف مسئله، تشخیص علت، داوری اخلاقی و پیشنهاد راهکار.', 92, 8),
('th-13', 'شانتو آینگار', 'Shanto Iyengar', 'shanto-iyengar', '/images/theorists/shanto-iyengar.svg', '۱۹۸۷', 'آمریکایی', 'روان‌شناسی سیاسی و اثرات رسانه', 'پرایمینگ رسانه‌ای و چارچوب‌های اپیزودیک در برابر موضوعی', 'شانتو آینگار استاد علوم سیاسی و ارتباطات در دانشگاه استنفورد است. پژوهش‌های آزمایشی او با همکاری دونالد کیندر نشان داد که اخبار تلویزیونی چگونه با تغییر زمینه‌های ذهنی (Priming)، قضاوت‌های سیاسی شهروندان را دستخوش دگرگونی می‌سازند.', 'رئیس آزمایشگاه ارتباطات سیاسی دانشگاه استنفورد، استاد دانشگاه‌های استنفورد، پرینستون و UCLA، مؤلف کتاب‌های بنیادین «اخباری که مهم هستند» و «آیا کسی مسئول است؟».', 'تلویزیون با تقلیل مسائل پیچیده ساختاری به رویدادهای گذرا و اپیزودیک، حس مسئولیت‌پذیری جمعی را فرسایش می‌دهد.', 91, 3),
('th-14', 'دنیس مک‌کوایل', 'Denis McQuail', 'denis-mcquail', '/images/theorists/denis-mcquail.svg', '۱۹۸۳', 'بریتانیایی', 'نظریه‌پردازی ارتباطات جمعی', 'طبقه‌بندی نظریه‌های ارتباط جمعی و هنجارهای رسانه‌ای', 'دنیس مک‌کوایل (۱۹۳۵–۲۰۱۷) برجسته‌ترین مؤلف متون آموزشی و تحلیلی ارتباطات جمعی در سطح بین‌المللی است. اثر جامع او با عنوان «درآمدی بر نظریه ارتباطات جمعی» دهه‌هاست که به عنوان متن درسی استاندارد در دانشگاه‌های سراسر دنیا تدریس می‌شود.', 'استاد ارتباطات دانشگاه آمستردام، بنیان‌گذار نشریه اروپایی ارتباطات، پژوهشگر نظریه‌های هنجاری رسانه و نظارت بر عملکرد دموکراتیک مطبوعات.', 'رسانه‌ها همزمان هم پنجره‌ای رو به جهان ناشناخته‌ها هستند و هم آینه‌ای که هویت خود ما را بازمی‌تابانند.', 93, 1),
('th-15', 'والتر لیپمن', 'Walter Lippmann', 'walter-lippmann', '/images/theorists/walter-lippmann.jpg', '۱۹۲۲', 'آمریکایی', 'روزنامه‌نگاری تحلیلی و فلسفه رسانه', 'تصاویر درون ذهن ما و شبه‌محیط رسانه‌ای (Pseudo-Environment)', 'والتر لیپمن (۱۸۸۹–۱۹۷۴) روزنامه‌نگار نام‌آور، برنده دو جایزه پولیتزر و فیلسوف سیاسی آمریکایی بود. کتاب تاریخی او «افکار عمومی» (۱۹۲۲) خاستگاه شناخت جهان نمادین و پیش‌درآمد نظریه برجسته‌سازی در علوم ارتباطات به حساب می‌آید.', 'بنیان‌گذار مجله نیوریپابلیک، برنده دو مدال پولیتزر، مشاور سیاست خارجی رؤسای جمهور آمریکا و نویسنده کتاب دوران‌ساز Public Opinion.', 'دنیای واقعی بزرگ‌تر و پیچیده‌تر از ادراک حسی ماست؛ رسانه‌ها شبه‌محیطی می‌سازند که ما پاسخ‌های واقعی‌مان را بر اساس آن تنظیم می‌کنیم.', 92, 6),
('th-16', 'کرت لوین', 'Kurt Lewin', 'kurt-lewin', '/images/theorists/kurt-lewin.svg', '۱۹۴۷', 'آلمانی / آمریکایی', 'روان‌شناسی اجتماعی و پویایی گروه', 'نظریه دروازه‌بانی (Gatekeeping Theory)', 'کرت لوین (۱۸۹۰–۱۹۴۷) پدر روان‌شناسی اجتماعی نوین و بنیان‌گذار نظریه میدان و پویایی گروهی است. مفهوم «دروازه‌بانان» که او نخستین بار در مورد کانال‌های تغذیه مطرح ساخت، توسط پژوهشگران ارتباطات برای تحلیل گزینش اخبار در رسانه‌ها اقتباس گردید.', 'مدیر مرکز تحقیقات پویایی گروه در دانشگاه MIT، استاد دانشگاه آیووا، پایه‌گذار مفاهیم بازخورد و تغییر سازمانی در علوم انسانی.', 'هیچ پدیده‌ای را نمی‌توان مستقل از محیط پیرامونش فهمید؛ اطلاعات از کانال‌هایی می‌گذرد که در هر نقطه دارای دربانانی تأثیرگذار است.', 90, 9),
('th-17', 'پیر بوردیو', 'Pierre Bourdieu', 'pierre-bourdieu', '/images/theorists/pierre-bourdieu.jpg', '۱۹۹۶', 'فرانسوی', 'جامعه‌شناسی فرهنگ و میدان قدرت', 'میدان ژورنالیسم، سرمایه نمادین و خشونت نمادین', 'پیر بوردیو (۱۹۳۰–۲۰۰۲) از نافذترین جامعه‌شناسان نیمه دوم قرن بیستم و استاد کولژ دو فرانس بود. اثر انتقادی او «درباره تلویزیون» وابستگی فزاینده حوزه رسانه به منطق بازار و پیامدهای فاجعه‌بار آن برای اندیشه و دموکراسی را کالبدشکافی کرد.', 'استاد کولژ دو فرانس، مدیر مطالعات مدرسه عالی علوم اجتماعی پاریس، مؤلف شاهکارهای جامعه‌شناسی «تمایز»، «تولید عقیده» و «درباره تلویزیون».', 'تلویزیون با ارائه اخبار تکراری و بی‌خطر، رویدادهای سرنوشت‌ساز را به حاشیه می‌راند و نوعی سانسور نامرئی اعمال می‌کند.', 94, 4),
('th-18', 'ژان بودریار', 'Jean Baudrillard', 'jean-baudrillard', '/images/theorists/jean-baudrillard.jpg', '۱۹۸۱', 'فرانسوی', 'فلسفه پساساختارگرا و نقد رسانه', 'وانموده و بیش‌واقعیت رسانه‌ای (Simulacra and Simulation)', 'ژان بودریار (۱۹۲۹–۲۰۰۷) فیلسوف و نظریه‌پرداز فرهنگی فرانسوی است که با طرح مفاهیمی چون «وانموده» و «بیش‌واقعیت»، نشان داد چگونه بازنمایی‌های رسانه‌ای در عصر مدرن جایگزین واقعیت اصیل شده و مرز میان حقیقت و سراب را محو نموده‌اند.', 'استاد جامعه‌شناسی دانشگاه پاریس نانتر، مؤلف کتاب‌های پیشگام «وانموده‌ها و شبیه‌سازی»، «جامعه مصرفی» و «اکران کامل».', 'ما وارد عصری شده‌ایم که در آن تصویر دیگر بازتاب‌دهنده واقعیت نیست، بلکه خود وانموده‌ای است که جهانی بی‌پشتوانه را جانشین جهان واقعی می‌سازد.', 93, 5),
('th-19', 'تئودور آدورنو', 'Theodor Adorno', 'theodor-adorno', '/images/theorists/theodor-adorno.jpg', '۱۹۴۷', 'آلمانی', 'نظریه انتقادی و مکتب فرانکفورت', 'صنعت فرهنگ و کالایی‌شدن آگاهی (Culture Industry)', 'تئودور ویزنگروند آدورنو (۱۹۰۳–۱۹۶۹) فیلسوف، جامعه‌شناس و نظریه‌پرداز فرهنگ مکتب فرانکفورت بود. او همراه هورکهایمر با خلق مفهوم «صنعت فرهنگ»، اثبات نمود که رسانه‌های توده‌ای هنر و فرهنگ را به ابزار انقیاد و استانداردسازی افکار توده‌ها تبدیل کرده‌اند.', 'رئیس مؤسسه تحقیقات اجتماعی دانشگاه فرانکفورت، نویسنده کتاب‌های مرجع «دیالکتیک روشنگری»، «اخلاق صغیر» و «شخصیت اقتدارطلب».', 'صنعت فرهنگ مدام به مصرف‌کنندگان وعده می‌دهد، اما آنچه عرضه می‌کند سرگرمی‌هایی تکراری برای حفظ وضع موجود است.', 93, 1),
('th-2', 'دونالد شاو', 'Donald Shaw', 'donald-shaw', '/images/theorists/donald-shaw.jpg', '۱۹۷۲', 'آمریکایی', 'ارتباطات سیاسی و روزنامه‌نگاری', 'تحلیل هم‌بستگی دستور کار رسانه و افکار عمومی', 'دونالد لوئیس شاو استاد برجسته و بازنشسته دانشکده رسانه و روزنامه‌نگاری هاسمن در دانشگاه کارولینای شمالی در چپل هیل است. او هم‌بنیان‌گذار نظریه تعیین اولویت رسانه‌ها و از پیشگامان تاریخ‌نگاری تحلیل محتوا در مطبوعات است.', 'استاد بازنشسته دانشگاه کارولینای شمالی، مؤلف بیش از ۲۰ جلد کتاب مرجع در تحلیل ارتباطات سیاسی و تاریخی از جمله «پیدایش برجسته‌سازی رسانه‌ای در آمریکا».', 'دستور کار رسانه‌ای همچون قطب‌نمایی است که جهت توجه جمعی ملت‌ها را مشخص می‌سازد.', 95, 2),
('th-20', 'ملوین دفلور', 'Melvin DeFleur', 'melvin-defleur', '/images/theorists/melvin-defleur.svg', '۱۹۷۶', 'آمریکایی', 'جامعه‌شناسی ارتباطات جمعی', 'نظریه وابستگی به سیستم رسانه‌ای (Media Dependency)', 'ملوین ال. دفلور (۱۹۲۳–۲۰۱۷) پژوهشگر پرسابقه علوم ارتباطات بود که نظریه وابستگی به سیستم رسانه را به همراه ساندرا بال-روکیچ فرمول‌بندی کرد. بر اساس این نظریه، در زمان بحران‌ها و تلاطم‌های اجتماعی، وابستگی شناختی و رفتاری جامعه به رسانه‌ها به نقطه اوج می‌رسد.', 'استاد در دانشگاه‌های بوستون، میامی و واشنگتن، نویسنده کتاب‌های کلاسیک «نظریه‌های ارتباطات جمعی» و «درک ارتباطات جمعی در آمریکا».', 'میزان قدرت رسانه‌ها در تعیین رفتار و نگرش، تابعی از وابستگی افراد و نهادها به اطلاعات رسانه‌ای است.', 89, 1),
('th-21', 'ساندرا بال-روکیچ', 'Sandra Ball-Rokeach', 'sandra-ball-rokeach', '/images/theorists/sandra-ball-rokeach.jpg', '۱۹۷۶', 'آمریکایی', 'بوم‌شناسی ارتباطی و اثرات رسانه‌ای', 'بوم‌شناسی ارتباطی و سیستم وابستگی به رسانه‌ها', 'ساندرا بال-روکیچ استاد برجسته ارتباطات و جامعه‌شناسی در دانشکده آننبرگ دانشگاه کالیفرنیای جنوبی (USC) است. او هم‌بنیان‌گذار نظریه وابستگی و رهبر پروژه بین‌المللی متامورفوز برای تحلیل پیوند رسانه‌ها و محله‌های شهری است.', 'استاد ممتاز دانشگاه کالیفرنیای جنوبی (USC)، برنده جوایز متعدد انجمن بین‌المللی ارتباطات، مؤلف کتاب «نظریه‌های ارتباطات جمعی» به همراه دفلور.', 'رسانه‌ها در خلاء عمل نمی‌کنند؛ ارتباطات مانند یک بوم‌سازگان پیچیده است که در آن افراد، رسانه‌ها و سیستم اجتماعی متقابلاً بر هم اثر می‌گذارند.', 88, 3),
('th-22', 'هنری جنکینز', 'Henry Jenkins', 'henry-jenkins', '/images/theorists/henry-jenkins.jpg', '۲۰۰۶', 'آمریکایی', 'رسانه‌های دیجیتال و همگرایی', 'فرهنگ همگرایی و رسانه مشارکتی (Convergence Culture)', 'هنری جنکینز (زاده ۱۹۵۸) استاد کرسی ارتباطات، روزنامه‌نگاری و هنرهای سینمایی دانشگاه کالیفرنیای جنوبی است. او مدیر سابق برنامه مطالعات تطبیقی رسانه در MIT بود و نظریه همگرایی رسانه‌ای و فرهنگ مشارکت هواداران را تبیین کرد.', 'مدیر برنامه رسانه‌ای MIT، استاد دانشگاه USC، مؤلف کتاب‌های پیشگام «فرهنگ همگرایی: تلاقی رسانه‌های کهن و نو» و «رسانه‌های گسترش‌پذیر».', 'همگرایی یک فرآیند فناورانه نیست، بلکه تحولی فرهنگی است که در آن مخاطبان از تماشاگران منفعل به تولیدکنندگان مشارکت‌جو تبدیل می‌شوند.', 92, 8),
('th-23', 'استیگ هیارورد', 'Stig Hjarvard', 'stig-hjarvard', '/images/theorists/stig-hjarvard.svg', '۲۰۰۸', 'دانمارکی', 'جامعه‌شناسی رسانه‌ای‌شدن', 'رسانه‌ای‌شدن فرهنگ و جامعه (Mediatization of Culture)', 'استیگ هیارورد استاد مطالعات فیلم و رسانه در دانشگاه کپنهاگ دانمارک است. اثر دوران‌ساز او مفهوم «رسانه‌ای‌شدن» را به عنوان یک فرآیند کلان مدرنیته هم‌ردیف با جهانی‌شدن و شهرنشینی در کانون تحلیل علوم ارتباطات قرار داد.', 'استاد دانشگاه کپنهاگ، رئیس اسبق انجمن اروپایی پژوهش و آموزش ارتباطات (ECREA)، نویسنده کتاب مرجع The Mediatization of Culture and Society.', 'رسانه‌ای‌شدن یعنی نفوذ منطق نهادی رسانه در تمام تاروپود جامعه؛ به گونه‌ای که سیاست، آموزش و دین برای دیده شدن ناگزیر از پذیرش منطق رسانه‌اند.', 90, 1),
('th-24', 'نیک کولدری', 'Nick Couldry', 'nick-couldry', '/images/theorists/nick-couldry.svg', '۲۰۰۳', 'بریتانیایی', 'جامعه‌شناسی رسانه و اخلاق ارتباطات', 'مناسک رسانه و استعمارگری داده‌ها (Data Colonialism)', 'نیک کولدری استاد جامعه‌شناسی و نظریه رسانه در مدرسه اقتصاد و علوم سیاسی لندن (LSE) است. او نقدهای پیشتازی درباره تمرکز قدرت نمادین در رسانه‌ها و استعمار جدید داده‌ها توسط پلتفرم‌های غول‌پیکر ارائه کرده است.', 'استاد دپارتمان رسانه و ارتباطات LSE، عضو هیئت تحریریه مجلات بین‌المللی ارتباطات، مؤلف کتاب‌های «مناسک رسانه‌ای» و «هزینه اتصال: استعمار داده‌ها».', 'قدرت رسانه‌ها در تحمیل این باور است که آن‌ها مرکز جامعه هستند؛ در حالی که حیات واقعی انسان‌ها در حاشیه‌های نادیده‌گرفته‌شده جریان دارد.', 89, 2),
('th-25', 'دانیل کانمن', 'Daniel Kahneman', 'daniel-kahneman', '/images/theorists/daniel-kahneman.jpg', '۱۹۸۱', 'آمریکایی / اسرائیلی', 'علوم شناختی و سوگیری‌های رسانه‌ای', 'نظریه چشم‌انداز و اثر چارچوب‌بندی بر قضاوت (Prospect Theory)', 'دانیل کانمن (۱۹۳۴–۲۰۲۴) برنده جایزه نوبل اقتصاد و استاد دانشگاه پرینستون بود. آزمایش‌های تجربی او به همراه عاموس تورسکی نشان داد که مغز انسان چگونه تحت تأثیر نحوه بیان رسانه‌ای (چارچوب سود در برابر زیان)، تصمیمات متضادی اتخاذ می‌کند.', 'برنده جایزه نوبل علوم اقتصادی ۲۰۰۲، استاد برجسته روان‌شناسی دانشگاه پرینستون، نویسنده اثر شاهکار بین‌المللی «تفکر، سریع و آهسته».', 'ذهن ما بر اساس اطلاعاتی قضاوت می‌کند که در دسترس آن قرار داده شده است؛ نحوه قاب‌بندی یک رویداد نحوه درک ما از واقعیت را می‌سازد.', 91, 4),
('th-26', 'دیوید آلتهاید', 'David Altheide', 'david-altheide', '/images/theorists/david-altheide.svg', '۱۹۷۹', 'آمریکایی', 'بوم‌شناسی رسانه و جامعه‌شناسی هراس', 'منطق رسانه (Media Logic) و گفتمان ترس عمومی', 'دیوید آلتهاید استاد ممتاز بازنشسته در دانشگاه ایالتی آریزونا است. او با معرفی مفهوم «منطق رسانه»، نشان داد که رسانه‌ها دارای قواعد زبانی و نمایشی خاصی هستند که سایر نهادهای جامعه برای بقا ناچار به انطباق با این منطق می‌گردند.', 'استاد ممتاز دانشگاه ایالتی آریزونا، نویسنده کتاب‌های جریان‌ساز «منطق رسانه» و «تروریسم و گفتمان ترس در اخبار».', 'منطق رسانه به شیوه سازمان‌دهی و انتقال نمادها اشاره دارد؛ هر پیامی باید با دستور زبان رسانه سازگار شود تا امکان پخش بیابد.', 88, 2),
('th-27', 'رولان بارت', 'Roland Barthes', 'roland-barthes', '/images/theorists/roland-barthes.jpg', '۱۹۵۷', 'فرانسوی', 'نشانه‌شناسی ساختارگرا و نقد فرهنگ', 'اسطوره‌شناسی رسانه و معانی ضمنی نشانه‌ها', 'رولان بارت (۱۹۱۵–۱۹۸۰) نشانه‌شناس، فیلسوف و منتقد نامدار فرانسوی است. کتاب درخشان او «اسطوره‌ها» نشان داد که چگونه متون رسانه‌ای و تبلیغات بازرگانی، مفاهیم ایدئولوژیک برساخته را به عنوان «امر طبیعی و بدیهی» به خورد جامعه می‌دهند.', 'استاد کرسی نشانه‌شناسی در کولژ دو فرانس، مؤلف کتاب‌های جاودانه «اسطوره‌ها»، «درجه صفر نوشتار» و «اتاق روشن».', 'وظیفه نقد نشانه‌شناختی آن است که نقاب طبیعی‌بودن را از چهره پیام‌های رسانه‌ای بردارد و خصلت تاریخی و ساختگی آن‌ها را برملا سازد.', 91, 8),
('th-28', 'ایلیا کتز', 'Elihu Katz', 'elihu-katz', '/images/theorists/elihu-katz.jpg', '۱۹۷۴', 'آمریکایی / اسرائیلی', 'جامعه‌شناسی ارتباطات و مطالعات مخاطب', 'رویکرد استفاده و خشنودی (Uses and Gratifications)', 'ایلیا کتز (۱۹۲۶–۲۰۲۱) از پیشگامان تغییر پارادایم در مطالعات مخاطب بود. او به جای بررسی منفعلانه تأثیر رسانه بر مخاطب، پرسش محوری را به این تغییر داد که: «مخاطبان چه استفاده‌هایی از رسانه‌ها می‌کنند و چه نیازهایی را برآورده می‌سازند؟»', 'استاد بازنشسته دانشگاه پنسیلوانیا و دانشگاه عبری، مؤلف کتاب‌های مرجع «کاربردهای ارتباطات جمعی» و «رویدادهای رسانه‌ای».', 'مخاطب موجودی فعال است که پیام‌های رسانه‌ای را برای برآوردن نیازهای شناختی، اجتماعی و عاطفی خود به خدمت می‌گیرد.', 90, 2),
('th-29', 'فیلیپ تیچنور', 'Phillip Tichenor', 'phillip-tichenor', '/images/theorists/phillip-tichenor.jpg', '۱۹۷۰', 'آمریکایی', 'ارتباطات جمعی و شکاف آگاهی', 'فرضیه شکاف آگاهی (Knowledge Gap Hypothesis)', 'فیلیپ جی. تیچنور استاد روزنامه‌نگاری و جامعه‌شناسی دانشگاه مینه‌سوتا بود. او به همراه همکارانش اثبات کرد که دسترسی بیشتر به جریان اطلاعات در جامعه، شکاف آگاهی میان طبقات فرادست و فرودست را به جای کاهش، تعمیق می‌بخشد.', 'استاد ارشد دانشگاه مینه‌سوتا، مؤلف مقالات دوران‌ساز در مجله Public Opinion Quarterly و هدایت‌کننده مطالعات نابرابری اطلاعاتی در رسانه.', 'اطلاعات بیشتر لزوماً به برابری دانش نمی‌انجامد؛ گروه‌های با پایگاه اقتصادی بالاتر، با سرعتی فزاینده‌تر از گروه‌های محروم اطلاعات را جذب می‌کنند.', 87, 1),
('th-3', 'مارشال مک‌لوهان', 'Marshall McLuhan', 'marshall-mcluhan', '/images/theorists/marshall-mcluhan.jpg', '۱۹۶۴', 'کانادایی', 'بوم‌شناسی رسانه و فلسفه ارتباطات', 'رسانه همان پیام است / دهکده جهانی', 'هربرت مارشال مک‌لوهان (۱۹۱۱–۱۹۸۰) فیلسوف، منتقد ادبی و نظریه‌پرداز برجسته کانادایی است که از او به عنوان پیشگوی عصر دیجیتال یاد می‌شود. او مفهوم «دهکده جهانی» را دهه‌ها پیش از پیدایش اینترنت خلق نمود و تحول فناوری را امتداد حواس بشری دانست.', 'رئیس مرکز فرهنگ و فناوری در دانشگاه تورنتو، مؤلف شاهکارهای فکری «کهکشان گوتنبرگ»، «شناخت رسانه‌ها: امتدادهای انسان» و «رسانه ماساژ است».', 'ما ابتدا ابزارهای ارتباطی‌مان را می‌سازیم و پس از آن، این ابزارها هستند که ما را بازمی‌آفرینند.', 98, 9),
('th-30', 'دیوید منینگ وایت', 'David Manning White', 'david-manning-white', '/images/theorists/david-manning-white.svg', '۱۹۵۰', 'آمریکایی', 'جامعه‌شناسی خبر و اتاق‌های خبر', 'مطالعه آقای گیتس و فرآیند گزینشگری در دروازه‌بانی', 'دیوید منینگ وایت (۱۹۱۷–۱۹۹۳) پژوهشگر پرسابقه روزنامه‌نگاری دانشگاه بوستون بود. مطالعه تجربی او روی یک سردبیر تلکس خبری به نام «آقای گیتس»، نخستین آزمون تجربی بود که سوگیری‌ها و سلایق فردی دروازه‌بان در پذیرش یا رد اخبار را عیان ساخت.', 'استاد و رئیس گروه روزنامه‌نگاری دانشگاه بوستون و ویرجینیا، مؤلف آثاری چون «فرهنگ توده‌ای: هنرهای عامه در آمریکا».', 'آنچه به عنوان اخبار جهان می‌خوانیم، از فیلتر ارزش‌ها و باورهای ذهنی دروازه‌بانان خبر عبور کرده است.', 88, 10),
('th-31', 'نیل پستمن', 'Neil Postman', 'neil-postman', '/images/theorists/neil-postman.jpg', '۱۹۳۱ - ۲۰۰۳', 'آمریکایی', 'بوم‌شناسی رسانه و منتقد فرهنگی', 'بوم‌شناسی رسانه و سرگرم‌شدن تا سرحد مرگ', 'نیل پستمن، نظریه‌پرداز برجسته ارتباطات و شاگرد و همکار مارشال مک‌لوهان بود که اصطلاح «بوم‌شناسی رسانه» را رسمیت بخشید و اثرات مخرب تلویزیون بر گفتمان عمومی را بررسی کرد.', 'استاد دانشگاه نیویورک (NYU) و بنیان‌گذار برنامه دکتری بوم‌شناسی رسانه در دانشگاه نیویورک.', 'تلویزیون ما را از فکر کردن بازنمی‌دارد، بلکه تفکر را به نمایش و سرگرمی تقلیل می‌دهد.', 90, 4),
('th-32', 'دالاس اسمایت', 'Dallas Smythe', 'dallas-smythe', '/images/theorists/dallas-smythe.svg', '۱۹۰۷ - ۱۹۹۲', 'کانادایی', 'اقتصاد سیاسی ارتباطات', 'کالایی‌شدن مخاطب (Audience Commodity)', 'پدر اقتصاد سیاسی ارتباطات که مقاله ماندگار او در سال ۱۹۷۷ با عنوان «نقطه کور مارکسیسم غربی»، توجه پژوهشگران جهان را به فروش زمان مخاطب توسط رسانه‌ها جلب کرد.', 'استاد دانشگاه سایمون فریزر و پیشگام تحلیل ساختاری ارتباطات تجاری در آمریکای شمالی.', 'در رسانه‌های تجاری، مخاطب خریدار نیست؛ مخاطب همان کالایی است که تولید و فروخته می‌شود.', 88, 2),
('th-33', 'یوهان گالتونگ', 'Johan Galtung', 'johan-galtung', '/images/theorists/johan-galtung.jpg', '۱۹۳۰ - ۲۰۲۴', 'نروژی', 'جامعه‌شناسی، مطالعات صلح و خبر', 'ارزش‌های خبری (News Values) و ژورنالیسم صلح', 'جامعه‌شناس و ریاضی‌دان نامدار نروژی که مدل ۱۲ عاملی ارزش‌های خبری را همراه با ماری هولمبو روگ صورتبندی کرد و بعدها مکتب ژورنالیسم صلح را بنیان گذاشت.', 'بنیان‌گذار مؤسسه بین‌المللی پژوهش‌های صلح اسلو (PRIO) و مشاور ارشد سازمان ملل متحد.', 'اگر رسانه‌ها ساختار اخبار را به نخبگان و خشونت محدود کنند، ادراک جامعه از جهان پیرامون به کلی واژگون خواهد شد.', 87, 2),
('th-34', 'ریچارد پتی', 'Richard Petty', 'richard-petty', '/images/theorists/richard-petty.svg', 'زاده ۱۹۵۱', 'آمریکایی', 'روان‌شناسی اجتماعی و اقناع', 'مدل احتمال بسط (Elaboration Likelihood Model - ELM)', 'روان‌شناس شناختی برجسته و استاد دانشگاه ایالتی اوهایو که همراه جان کاسیوپو یکی از پرکاربردترین الگوهای اقناع رسانه‌ای در جهان را صورت‌بندی نمود.', 'استاد ممتازه روان‌شناسی در دانشگاه اوهایو استیت و عضو آکادمی هنرها و علوم آمریکا.', 'دوام نگرش ناشی از تفکر عمیق و منطقی، با اقناع ناشی از نشانه‌های زودگذر سطحی هرگز قابل مقایسه نیست.', 85, 2),
('th-35', 'کارل وایک', 'Karl Weick', 'karl-weick', '/images/theorists/karl-weick.svg', 'زاده ۱۹۳۶', 'آمریکایی', 'ارتباطات سازمانی و نظریه سیستم‌ها', 'حس‌سازی سازمانی (Sensemaking in Organizations)', 'پژوهشگر برجسته رفتارهای سازمانی که مفهوم خلق معنا و حس‌سازی در شرایط بحرانی و پرابهام را وارد دانش مدیریت ارتباطات نمود.', 'استاد ممتاز روان‌شناسی و رفتار سازمانی در دانشگاه میشیگان.', 'چگونه بدانم به چه چیزی فکر می‌کنم تا زمانی که نبینم چه چیزی می‌گویم؟', 84, 1),
('th-36', 'لوسی کونگ', 'Lucy Küng', 'lucy-kung', '/images/theorists/lucy-kung.svg', 'پژوهشگر معاصر', 'سوئیسی / بریتانیایی', 'مدیریت و استراتژی رسانه', 'مدیریت استراتژیک در رسانه و رهبری تحول دیجیتال', 'از سرشناس‌ترین صاحب‌نظران بین‌المللی در حوزه استراتژی رسانه، دوسوتوانی سازمانی و گذار بنگاه‌های خبری به محیط‌های دیجیتال و هوش مصنوعی.', 'پژوهشگر ارشد مؤسسه رویترز برای مطالعه ژورنالیسم در دانشگاه آکسفورد.', 'چالش اصلی رسانه‌ها فناوری نیست، بلکه بازآفرینی فرهنگ، ذهنیت مدیران و ساختار سنتی تصمیم‌گیری است.', 85, 2),
('th-37', 'زیزی پاپاچاریسی', 'Zizi Papacharissi', 'zizi-papacharissi', '/images/theorists/zizi-papacharissi.svg', 'پژوهشگر معاصر', 'یونانی / آمریکایی', 'ارتباطات سیاسی و رسانه‌های اجتماعی', 'عمومیت‌های عاطفی (Affective Publics)', 'استاد نامدار ارتباطات و علوم سیاسی در دانشگاه ایلینوی شیکاگو و سردبیر ارشد نشریه Social Media + Society، پیشگام پژوهش پیرامون پیوند احساسات و سیاست در شبکه‌های اجتماعی.', 'مدیر دپارتمان ارتباطات دانشگاه ایلینوی شیکاگو و پژوهشگر ارشد فضای عمومی دیجیتال.', 'شبکه‌های اجتماعی صرفاً ابزار انتشار خبر نیستند، بلکه بستر هم‌طنین‌شدن احساسات جمعی‌اند.', 86, 3),
('th-38', 'دیوید هزموندهالگ', 'David Hesmondhalgh', 'david-hesmondhalgh', '/images/theorists/david-hesmondhalgh.svg', 'زاده ۱۹۶۳', 'بریتانیایی', 'صنایع فرهنگی و اقتصاد سیاسی ارتباطات', 'نظریه صنایع فرهنگی (The Cultural Industries)', 'استاد رسانه، موسیقی و فرهنگ در دانشگاه لیدز و نویسنده کتاب مرجع «صنایع فرهنگی» که جامع‌ترین تحلیل انتقادی از مدیریت ریسک در تولیدات نمادین و سرگرمی را ارائه داده است.', 'استاد دانشگاه لیدز و پژوهشگر پیشرو در مطالعات رسانه و اقتصاد سیاسی فرهنگ.', 'دیجیتالی‌شدن نتوانست تمرکز شرکت‌های غول‌پیکر بر بازار فرهنگ و کالایی‌شدن خلاقیت را از میان ببرد.', 88, 1),
('th-39', 'دیوید نیبورگ', 'David Nieborg', 'david-nieborg', '/images/theorists/david-nieborg.svg', 'پژوهشگر معاصر', 'هلندی / کانادایی', 'پلتفرمی‌شدن و مطالعات بازی', 'پلتفرمی‌شدن تولید رسانه (Platformization)', 'استاد مطالعات رسانه در دانشگاه تورنتو و یکی از نظریه‌پردازان اصلی مفهوم پلتفرمی‌شدن و کالای مشروط در اقتصاد فرهنگ دیجیتال.', 'استاد دانشگاه تورنتو و عضو ارشد مرکز مطالعات فرهنگ دیجیتال.', 'در عصر پلتفرم‌ها، محتوای فرهنگی دیگر ثابت نیست؛ این محتوا کالایی مشروط به تغییرات مداوم الگوریتم است.', 83, 2),
('th-4', 'یورگن هابرماس', 'Jürgen Habermas', 'jurgen-habermas', '/images/theorists/jurgen-habermas.jpg', '۱۹۶۲', 'آلمانی', 'نظریه انتقادی و فلسفه سیاسی', 'حوزه عمومی و کنش ارتباطی (Public Sphere)', 'یورگن هابرماس (زاده ۱۹۲۹) فیلسوف و جامعه‌شناس پرآوازه آلمانی و چهره شاخص نسل دوم مکتب فرانکفورت است. نظریه او درباره زوال و احیای حوزه عمومی و لزوم گفت‌وگوی عقلانی عاری از سلطه، متن بنیادین فلسفه رسانه در جهان معاصر است.', 'استاد دانشگاه فرانکفورت، برنده جوایز بین‌المللی صلح کانت و هولبرگ، نویسنده آثار اثرگذار «دگرگونی ساختاری حوزه عمومی» و «نظریه کنش ارتباطی».', 'حوزه عمومی فضایی رها از سانسور و سلطه است که در آن اقتدار استدلال جایگزین استدلال بر پایه اقتدار می‌شود.', 97, 3),
('th-5', 'استوارت هال', 'Stuart Hall', 'stuart-hall', '/images/theorists/stuart-hall.jpg', '۱۹۷۳', 'بریتانیایی / جامائیکایی', 'مطالعات فرهنگی و نشانه‌شناسی', 'مدل رمزگذاری / رمزگشایی (Encoding/Decoding)', 'استوارت مک‌فیل هال (۱۹۳۲–۲۰۱۴) جامعه‌شناس فرهنگی و نظریه‌پرداز پیشگام مکتب بیرمنگام بود. او نشان داد که متون رسانه‌ای دارای معنای ثابت نیستند، بلکه مخاطبان بر پایه پایگاه اجتماعی خود می‌توانند آنها را به صورت سلطه‌پذیر، مذاکره‌ای یا تقابلی رمزگشایی کنند.', 'مدیر مرکز مطالعات فرهنگی معاصر بیرمنگام (CCCS)، استاد جامعه‌شناسی دانشگاه آزاد بریتانیا، رئیس انجمن بریتانیایی جامعه‌شناسی و مؤلف آثار کلیدی پیرامون بازنمایی، هویت و ایدئولوژی.', 'معنا امری نهایی و بسته‌بندی‌شده نیست؛ معنا همواره در جریان عمل گفتمانی و تفسیر مخاطب تولید می‌شود.', 96, 3),
('th-6', 'جورج گربنر', 'George Gerbner', 'george-gerbner', '/images/theorists/george-gerbner.jpg', '۱۹۷۶', 'آمریکایی / مجارستانی', 'جامعه‌شناسی رسانه و تحلیل کاشت', 'نظریه کاشت و سندرم جهان بی‌رحم (Cultivation Theory)', 'جورج گربنر (۱۹۱۹–۲۰۰۵) دانشمند برجسته علوم ارتباطات و رئیس ۲۵ ساله دانشکده آننبرگ دانشگاه پنسیلوانیا بود. پروژه ماندگار او موسوم به «شاخص‌های فرهنگی» نشان داد مصرف مداوم تصاویر تلویزیونی، جهان‌بینی هراس‌آلود و حس ناامنی مفرط در جامعه می‌کارد.', 'رئیس دانشکده ارتباطات آننبرگ دانشگاه پنسیلوانیا (۱۹۶۴-۱۹۸۹)، پایه‌گذار جنبش محیط‌زیست فرهنگی، مؤلف بیش از صدها تحقیق درباره بازنمایی خشونت و جنسیت در تلویزیون.', 'کسی که داستان‌های یک فرهنگ را روایت می‌کند، در واقع قواعد و احساسات مشترک آن جامعه را اداره می‌نماید.', 95, 5),
('th-7', 'الیزابت نوئل-نویمان', 'Elisabeth Noelle-Neumann', 'elisabeth-noelle-neumann', '/images/theorists/elisabeth-noelle-neumann.jpg', '۱۹۷۴', 'آلمانی', 'روان‌شناسی اجتماعی و افکار عمومی', 'نظریه مارپیچ سکوت (Spiral of Silence)', 'الیزابت نوئل-نویمان (۱۹۱۶–۲۰۱۰) جامعه‌شناس و دانشمند علوم سیاسی آلمانی بود که سازوکار نظرسنجی مدرن در آلمان را با تأسیس مؤسسه آلنزباخ پایه‌ریزی کرد. نظریه مارپیچ سکوت او توضیح می‌دهد که چگونه ترس از انزوای اجتماعی افراد را وادار به پنهان‌سازی عقاید اقلیت می‌کند.', 'استاد ارتباطات دانشگاه یوهانس گوتنبرگ ماینتس، رئیس انجمن جهانی پژوهش‌های افکار عمومی (WAPOR)، مؤلف کتاب کلاسیک «مارپیچ سکوت: افکار عمومی؛ پوست دوم ما».', 'تمایل به حفظ موقعیت اجتماعی و ترس از طرد شدن، انسان‌ها را به ناظران پیوسته فضای افکار عمومی تبدیل می‌کند.', 94, 1),
('th-8', 'اروینگ گافمن', 'Erving Goffman', 'erving-goffman', '/images/theorists/erving-goffman.jpg', '۱۹۷۴', 'کانادایی / آمریکایی', 'جامعه‌شناسی خرد و تعامل‌گرایی نمادین', 'تحلیل چارچوب‌بندی و بازنمایی خود در زندگی روزمره', 'اروینگ گافمن (۱۹۲۲–۱۹۸۲) به عنوان تأثیرگذارترین جامعه‌شناس آمریکایی قرن بیستم در حوزه خرد شناخته می‌شود. کتاب «تحلیل چارچوب» او در سال ۱۹۷۴ الگویی جامع برای درک ساختاربندی ذهنی و بسته بندی خبر توسط رسانه‌ها ارائه داد.', 'استاد دانشگاه کالیفرنیا در برکلی و دانشگاه پنسیلوانیا، رئیس انجمن جامعه‌شناسی آمریکا (ASA)، نویسنده شاهکارهای «نمایش خود در زندگی روزمره» و «تحلیل چارچوب».', 'چارچوب‌ها تعریف ما از موقعیت را سامان می‌دهند و مشخص می‌سازند در این صحنه چه چیزی اهمیت دارد.', 93, 21),
('th-9', 'پل لازارسفلد', 'Paul Lazarsfeld', 'paul-lazarsfeld', '/images/theorists/paul-lazarsfeld.jpg', '۱۹۴۴', 'اتریشی / آمریکایی', 'جامعه‌شناسی تجربی و روش‌شناسی ارتباطات', 'جریان دو مرحله‌ای ارتباط و رهبران افکار (Two-Step Flow)', 'پل فلیکس لازارسفلد (۱۹۰۱–۱۹۷۶) از ستون‌های اصلی پایه‌گذاری پژوهش‌های نوین ارتباطی در ایالات متحده است. مطالعات ماندگار او در پروژه شهرستان اری نشان داد رسانه‌ها مستقیماً رفتار رأی‌دهندگان را کنترل نمی‌کنند، بلکه نفوذ از کانال رهبران فکری محلی عبور می‌کند.', 'بنیان‌گذار دفتر تحقیقات اجتماعی کاربردی دانشگاه کلمبیا، استاد تمام دانشگاه کلمبیا، مؤلف مشترک کتاب‌های تاریخی «انتخاب مردم» و «نفوذ شخصی».', 'پیام‌های رسانه‌ای ابتدا به فعالان فکری جامعه می‌رسند و سپس از میان روابط چهره‌به‌چهره به عموم سرایت می‌کنند.', 94, 11);
